insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-44662','course','Основы продаж в ресторане: как увеличить доход через искусство сервиса',null,'{"id":"guru-44662","title":"Основы продаж в ресторане: как увеличить доход через искусство сервиса","shortTitle":"Основы продаж в ресторане: как увеличить доход через искусство сервиса","coverLabel":"Основы продаж в ресторане: как увеличить до…","description":"Работа с гостями и развитие продаж через сервис.","kind":"course","brand":"90-е","departments":["Зал","Бар","Кухня","Арт","Кальян","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Что такое гостеприимство?","text":"Тепло без фамильярности: как это работает?\n\nНастоящее гостеприимство — это не «брат» и не «молодой человек». Это не «погнали» и не «секундочку, зайду за угол».\n\nЭто внимание, такт и настроение, которое ты создаёшь без лишних слов.\n\nТепло — это не «на ты».\n\nЭто — когда:\n\n✔️ ты замечаешь, что гость замёрз, и предлагаешь плед.\n\n✔️ подаёшь напиток с комментарием, а не просто ставишь на стол.\n\n✔️ запоминаешь любимую позицию постоянного гостя.\n\n✔️ говоришь «буду рядом, если что», вместо «зовите, если надо».\n\nФамильярность — это про тебя.\n\nТепло — это про гостя.\n\nТвоя задача — создать ощущение заботы и уюта, не переходя границы.\n\nЧтобы гость почувствовал себя своим, но не поймал кринж.\n\nМы не друзья, но мы рядом. Не семья, но с уважением. Не на «ты», но с душой.\n\nЭто и есть стильный сервис — искренний, корректный, тёплый","images":["assets/remaining-courses/guru-44662-106030-0.jpg"],"links":[],"id":"106030"},{"title":"Гостеприимство и продажи","text":"Гостеприимство и продажи\nОбсудим самую животрепещущую тему для всех работников ресторанов — продажи и повышение среднего чека.\n\nНаверняка вам часто говорят, что нужно больше продавать, а вот как продавать, что продавать, и главное, кому продавать — ответы на эти вопросы вам придется искать самостоятельно. Я постараюсь вам в этом помочь.\n\nВо-первых, сразу хочу развенчать популярный миф о том, что делать доп. продажи можно сделать только на избранных, особо хороших столиках. На самом деле, если мы умеем предлагать блюда правильно, то дополнительные предложения можно и нужно делать всем гостям. Это не будет восприниматься как навязывание и втюхивание. Дополнительные предложения — вовсе не попытка вытащить из кармана гостя больше денег! Дополнительные предложения — ваше гостеприимство. Сложно разобраться с этим понятием? Так что же такое гостеприимство? Ведь наверняка вы и так улыбаетесь гостям, разве этого не достаточно?\n\nПредставим ситуацию:\n\nК вам в гости домой приходит подруга или бабушка. Вы же встретите ее на пороге, покажете, куда можно повесить верхнюю одежду, где можно помыть руки, и куда присесть. Вы явно сразу предложите самый вкусный напиток и угостите пирогом, печеньем, шоколадом — поставите на стол все самое вкусное, что есть дома. Так вы дома проявляете гостеприимство.\n\nА теперь давайте мысленно вернемся в ресторан. Давайте представим, что вы не просто работаете официантом в ресторане, а вы — его хозяин. Вы с любовью и заботой создавали это место, чтобы угощать гостей вкусными блюдами и напитками. Вы хотите не продать, а предложить самое лучшее, что у вас есть! Уже легче?  Будьте искренними и предупредительными с гостями ресторана. Относитесь к ним так, как вы бы хотели, чтобы относились к вам. Это и называется настоящим гостеприимным сервисом.\n\nПонимать тут нужно только то, что и кому можно предложить. Для этого попробуйте поставить себя на место гостя. Кто он? Как бы вы хотели, чтобы к вам относились? Почему он выбрал именно этот ресторан? Что, на ваш взгляд, тут должно понравиться этому гостю? А если бы он был вашим другом, или родственником, то что бы вы ему предложили?\n\nДля того чтобы сильно облегчить себе жизнь, но вместе с тем поднять продажи, составьте для себя список самых лучших на ваш взыскательный вкус блюд в вашем заведении. Ваши личные предпочтения — ваш ключ к эффективным предложениям. Именно так это и работает — невозможно искренне предложить то блюдо, которое лично у вас не вызывает положительных эмоций. Тут у вас огромное преимущество — вы знаете все блюда в ресторане, и можете составить себе такой топ. При этом, не забывайте, что вы — связующее звено между талантом шеф-повара и гостем. Вам нужно представить гостю ваши фирменные блюда в выгодном свете.\n\nВы работаете в итальянском ресторане? Наверняка у вас готовят восхитительную пасту карбонара, с ломтиками поджаренного бекона или панчеты, густым соусом, свежемолотым черным перцем, а перед подачей в тарелку насыпают горсть тертого пармезана. Или, может быть, вы работаете в бургерной, где на гриле поджаривают рубленые котлеты из мраморной говядины, на котлету выкладывают ломтик сыра чеддар, спелые овощи и салатные листья, и подают в мягких пшеничных булочках с авторским соусом?\n\nСкажите, вам уже захотелось есть? А что я по вашему сделала? Я сейчас всего лишь создала в ваших головах образы этих вкусных блюд, описав вам процесс их приготовления. Так вот, вам нужно сделать все то же самое! Подумайте, за какими блюдами вы сами хотели бы прийти в свой ресторан и почему. Вспомните, как их готовят и опишите процесс. Пусть в вашем топе будет 10 блюд — этого хватит для успешных продаж!\n\nА теперь можно перейти непосредственно к продажам.\n\nПервое правило хорошего продажника — только конкретные предложения. Никаких “Может быть” “Что-нибудь”. Только конкретика, только хардкор:) Предлагаем определенное блюдо или доп, один или два на выбор.\n\n1: Берем частицу “не” и забываем навсегда. Как и все остальные подобные слова с негативной окраской. “Не желаете ли?” “Не хотите ли?”.\n\n2: забудьте про уменьшительно-ласкательные суффиксы и неинформативные эпитеты! Это звучит смешно, заискивающе и непрофессионально. Вы же официанты, а не халдеи. И потом, ваш гость — взрослый человек! Он хочет суп, а не супчик, десерт, а не десертик. Уважайте себя и гостей. Эпитеты, которые не несут никакой информации — вкуснейший, нежнейший, замечательный, отличный — не нужно их использовать. Это никак не поможет вашим продажам.\n\nА как же нужно предлагать блюдо гостю?\n\nПредлагать нужно вовремя. Как только гость сел за стол, подойдите, поздоровайтесь. Спросите, что принести из напитков. Не “Может быть, что-то из напитков?”, а конкретно. Сразу принести воды или сок? Принимая заказ, дополняйте его своими рекомендациями.\nПредлагайте стартеры, закуски. Прекрасно подойдут маленькие, разжигающие аппетит перед основным блюдом закуски — салаты, тартары, севиче. А на компанию — большие красивые закуски в стол. “На закуску рекомендую антипасти. Это всё богатство Италии в одном блюде — панчетта, брезаола, сыры пармезан и пекорино, маслины, артишоки и гриссини”. К горячему хорошо продаются гарниры. Десерты уместно предлагать после трапезы.\n\nРекомендуйте!\n\nРассказывайте приятные факты. Увлекайте. Описывайте технологию. Создайте в голове гостя образ! “Только что испекли свежую порцию круассанов! Мы готовим их по французской технологии. Наш кондитер вручную раскатывает тесто со сливочным маслом на множество слоев, поэтому внутри они совершенно воздушные, пахнут молоком, а верхний слой — хрустящий и золотистый” Или “В качестве закуски попробуйте наш тартар. Мы замешиваем кубики отборной говядины с двумя видами лука, перцем и кремом из пармезана, подаем с теплым сырным профитролем”\nРассказывайте вкусные истории. У вас в ресторане фермерский сыр? Может быть, у вас особый авторский рецепт соусов для бургеров? Это и есть ваша фишка! Сделайте так, чтобы гости об этом узнали! “...А сыр для нашего ресторана специально готовят на ферме в Подмосковье, из очень качественного молока по итальянской технологии. Попробуете буратту с томатами и печеным перцем?”\nНе перегружайте гостя информацией. Одна-две интригующие фразы.\nНе отвлекайте гостей. Не подходите во время беседы, телефонного разговора, трогательных сцен и объятий.\n\nА если гость заказал всего лишь одну чашку кофе? Чайник чая? Бокал пива?\n\nК чаю: мята, чабрец, лимон, мед, десерты\n\nК кофе: молоко, сливки, сиропы, корицу\n\nК пиву: закуски, горячие закуски, горячие блюда\n\nИ так далее\n\nГость заказал чайник черного чая. Вот и возможность для дополнительной продажи!\n\nЗаварить вам чай с мятой или чабрецом? - Тут лучше не говорить “добавить мяту или чабрец”, лучше показывайте уют этого процесса, рисуйте процесс приготовления.\n\nСравните с “Не желаете-ли мяту или чабрец?”\n\nГостья заказала чашку кофе? Предложите маленькую сладость. У вас есть в меню печенье или конфеты? Так вы увидите, расположен ли он к сладкому в принципе, и с большей вероятностью порадуете гостеприимством и заботой.\n\nХотите трюфель к кофе? Их каждый день готовят в нашей кондитерской из бельгийского темного шоколада с коньяком.\n\nДополнительное предложение — это не продажи, это экскурсия, которую вы проводите для своих гостей по меню вашего заведения.\n\nПомните, не гость, а вы здесь \"на коне\", потому что знаете всё о блюдах, и именно вы управляете продажами ресторана. Вы, официанты, а не маркетолог или управляющий. В ваших силах сделать так, чтобы гость к вам вернулся. Предложить что-то можно любому человеку с любым бюджетом.\n\nМетоды повышения среднего чека\n\nЕсть две методики продаж, которые активно используются в общепите.\n\nОдна из них — апселлинг. Она направлена на увеличение стоимости блюд.Другая — кросселлинг — на увеличение позиций в меню.\n\nАпселлинг (upselling) — это предложение более дорогого варианта.\n\nНапример, предлагается пицца большего диаметра, или двойная порция блюда. Можно внести в меню авторский рецепт от шеф-повара или фирменный кофе по цене выше аналогов.\n\nМетодика кросселлинг (сross selling) помогает увеличить позиции в чеке. Это продажа дополнительных ингредиентов, соусов, сиропов. Если основное заказанное блюдо придется ждать долго, предложите гостям легкие закуски.\n\n\"Ёлочка\"\n\nПринцип «Елочки» давно известен в среде рестораторов.\n\nОн прост, эффективен и не требует затрат на внедрение.\n\n«Елочка» — это выбор среди альтернатив, предложенных официантом. В основе метода лежит принцип деления. Наводящие вопросы, которые задает официант, должны разбивать меню или его разделы на части. Таким образом, отвечая на вопросы официанта, гость выбирает нужные ему блюда из представленного разнообразия позиций в меню. При этом важно понимать, что «Елочка» в первую очередь преследует цель продать то, что максимально выгодно нам, однако крайне важно сделать это таким образом, чтобы гость остался доволен.\n\nПредставьте себе следующую картину: гость впервые пришел в ваш ресторан, официант не просто положил перед ним внушительных размеров меню и удалился на 10-15 минут, а предложил свою помощь в выборе. Задавая наводящие вопросы, он попытается как можно быстрее узнать предпочтения, чтобы предложить желанные для гостя и выгодные для ресторана блюда.\n\nГость, скорее всего, останется доволен после посещения ресторана: он получил именно те блюда, которые хотел, не тратя много времени на изучение всего меню ресторана. При этом у него сложилось впечатление, что выбор не был ему навязан. Официант постарался подстроиться под предпочтения гостя, при этом предложив ему блюда, например, поставленные на апселлинг. Таким образом, мы продали то, что выгоднее для нас, однако вероятность повторного посещения ресторана все равно увеличилась.\n\nДоказано, что довольный клиент расскажет о ресторане 1-2 людям, в то время как недовольный сообщит примерно 10 своим знакомым, что с вами не стоит иметь дело. Хорошая репутация на вес золота, не стоит забывать об этом.\n\nПредлагаем вам рассмотреть метод «Елочки» на практике.\n\nПрактическое применение\n\nЧтобы применять метод «Елочки» на практике, официант должен хорошо знать меню, чтобы выводить гостя на выгодные для ресторана позиции.\n\nНапример, официант может поинтересоваться, плотно или легко хочет поесть гость. Если гость желает поесть плотно, официант должен предложить ему на выбор рыбные, мясные или другие блюда, подпадающие под данную категорию, чтобы начать ветвление из этих разделов меню. Если же гость желает просто перекусить, то логичнее будет предложить ему что-нибудь из горячих или холодных закусок, десертов и так далее.\n\nТеперь от официанта требуется «прощупать» предпочтения гостя, чтобы провести его только по нужным позициям меню. Если гость предпочел мясные блюда рыбным, необходимо спросить, какое именно мясо он любит: свинину, курицу, говядину, баранину и так далее, снова предложив гостю альтернативы. После ответа стоит поинтересоваться о любимых способах приготовления блюда. Вполне вероятно, что гость остановит свой выбор на тушеном мясе, а не на жареном. Это еще в большей степени поможет сузить круг поисков.\n\nМожно задать еще один наводящий вопрос о гарнире. Если выяснится, что гость предпочитает, картофель, а на предыдущем шаге он выбрал свинину, то можно предложить ему на выбор, например, жаркое из свинины по-домашнему или тушеную свинину с картофелем.\n\nПо тому же самому принципу должен происходить и выбор напитков из коктейльного меню, блюд из меню японского, да и вообще любых товаров бара и кухни.\n\nПодведем итоги. Какие вопросы задавал официант во время общения с гостем?\n\nВы желаете плотно поесть или перекусить?\n\nГость захотел поесть плотно, поэтому официанту необходимо предложить ему блюда, подпадающие под данную категорию в меню.\n\nКакие блюда вы предпочитаете: мясные, рыбные, из морепродуктов?\nГость предпочел мясные блюда.Теперь официанту необходимо понять, какое конкретно мясо хочет попробовать гость.\nКакое мясо вы больше любите: курицу, свинину, говядину, баранину?\n\nПредположим, что гость предпочел свинину. Требуется понять, какой способ приготовления ему больше по душе.\n\nКакой способ приготовления мяса вам больше подойдет?\nГость выбрал тушеное мясо, теперь следует определиться с гарниром.\nКакой гарнир к мясу вы предпочитаете?\n\nПосле ответа гостя предлагаем ему блюда из меню, соответствующие заявленным критериям. В нашем случае такими блюдами являются жаркое из свинины по-домашнему или тушеная свинина с картофелем.\n\nЧтобы извлечь из процесса максимальную выгоду, предлагайте гостю позиции, поставленные на апселлинг.\n\nДоказано, что из всего перечисленного человек обычно запоминает первый и последний пункты, поэтому высока вероятность, что гость выберет именно те блюда, которые были названы в начале или в конце.\n\nДля иллюстрации примера мы нарисовали дерево выбора для рассмотренной выше ситуации.\n\nПопробуйте поупражняться с коллегами-официантами.\n\nПусть они разобьют меню вашего заведения по принципу «Елочки» для 5-10 разных гостей и «прогонят» вышеизложенную схему, заменив в ней параметры. При этом один из ваших коллег может выступить в роли гостя, а другой будет официантом. Увидите, это принесет свои плоды.\n\nНа примере мы убедились, что метод «Елочки» позволяет быстрее провести гостя по «лабиринтам» меню и предложить ему то, что он «действительно» хочет. Но и здесь есть несколько ограничений. Во-первых, вы должны безукоризненно ориентироваться в меню ресторана, чтобы твердо знать какие позиции находятся в каком разделе. Так вы гарантированно сможете увеличить прибыль. Стажеры, которые пока не допускаются до работы с клиентами, также могут практиковаться друг на друге, заучивая меню в процессе его разбиения по методу «Елочки».\n\nВо-вторых, не стоит быть излишне навязчивым: у гостя должно сложиться впечатление, что выбор он делал самостоятельно.","images":["assets/remaining-courses/guru-44662-105990-0.jpg","assets/remaining-courses/guru-44662-105990-1.jpg","assets/remaining-courses/guru-44662-105990-2.jpg","assets/remaining-courses/guru-44662-105990-3.jpg","assets/remaining-courses/guru-44662-105990-4.jpg","assets/remaining-courses/guru-44662-105990-5.jpg","assets/remaining-courses/guru-44662-105990-6.jpg","assets/remaining-courses/guru-44662-105990-7.jpg","assets/remaining-courses/guru-44662-105990-8.jpg"],"links":[{"title":"безукоризненно ориентироваться в меню ресторана","url":"http://traktir.ru/publications/14900/"}],"id":"105990"}],"outline":[{"type":"lesson","title":"Что такое гостеприимство?","lessonIndex":0},{"type":"lesson","title":"Гостеприимство и продажи","lessonIndex":1},{"type":"test","title":"Тест \"Гостеприимство, продажи и средний чек\""}],"testIds":["95471"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-25724','course','Разговорный английский для официантов',null,'{"id":"guru-25724","title":"Разговорный английский для официантов","shortTitle":"Разговорный английский для официантов","coverLabel":"Разговорный английский для официантов","description":"Английский язык для общения с гостями ресторана.","kind":"course","brand":"90-е","departments":["Зал","Бар","Кухня","Арт","Кальян","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Приветствие гостей","text":"Приветствуем гостей\n\nКурс предоставлен школой иностранного языка Star Talk. Читает преподаватель Чиркова Елена.\n\nPresenter:\n\nВсем привет/ Hi everyone. В этой серии видео мы научим вас общаться с иностранными посетителями на английском языке. Сегодня давайте разберем как можно поприветствовать гостей ресторана или кафе.\n\nДавайте рассмотрим типичную ситуацию.\n\nHost/Hostess: Good evening sir/madam. Do you have a reservation?\n\nGuest: Yes, the name is White.\n\nH: Ah yes Ms/Mr.White. Table for 2?\n\nG: Yes, that’s right. Smoking section, please.\n\nH: I am sorry, sir/madam. There is no smoking in restaurants in Russia.\n\nG: Oh OK.\n\nH: Please follow me. (pointing at the table) Will this table be all right?\n\nG: Yes, thank you.\n\nH: Here are your menus. Your waiter will come shortly.\n\nДавайте разберем. Мы говорим Good evening, так как диалог происходит вечером. Утром мы говорим Good morning, днем – Good afternoon. А если вдруг вы забыли или не уверены, какой вариант использовать, скажите просто Hello.\n\nDo you have a reservation? – английский эквивалент русской фразы «У вас забронирован стол?» Ключевое слово здесь – reservation, поэтому самое главное – запомнить его.\n\nС помощью фразы Table for 2? Или Party of 2? Мы спрашиваем о количестве человек в группе. Party здесь переводится не «вечеринка», конечно, а «группа/компания”.\n\nPlease follow me. – Пожалуйста, следуйте за мной. Не забывайте говорить Please – оно «смягчит» любую фразу.\n\nА что, если гость не забронировал столик?\n\nHost/Hostess: Good morning sir/madam. Do you have a reservation?\n\nG: No, I don’t.\n\nH: I am sorry. We don’t have available table at the moment. Would you like to wait?\n\nG: How long is the wait?\n\nH: 10-15 minutes sir/madam.\n\nG: Ok, I’ll wait.\n\nВарианты замен:\n\nБолее легкий варианты: There are no free tables now. / The restaurant is full at the moment.\n\nDo you want to wait? Will you wait?\n\nВы можете практиковать фразы, повторяя их за нашими героями, а затем разыгрывая ситуации с коллегой.\n\nНа сегодня всё. Увидимся в следующих видео. Have a good day and see you soon!\n\nХочешь изучить тему подробнее? Жми на http://www.start2talk.ru/","images":["assets/remaining-courses/guru-25724-42706-0.jpg","assets/remaining-courses/guru-25724-42706-1.jpg"],"links":[{"title":"http://www.start2talk.ru/","url":"http://www.start2talk.ru/"},{"title":"Видео к уроку","url":"https://www.youtube.com/embed/wQ8EE1XVidU?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25724%2Flesson%2F42706&aoriginsup=1&vf=1"}],"id":"42706"},{"title":"Прием заказа","text":"Прием заказа\n\nКурс предоставлен школой иностранного языка Star Talk. Читает преподаватель Чиркова Елена.\n\nМы продолжаем наши видео уроки и сегодня поработаем над приемом заказа.\n\nНачнем с диалога.\n\nServer: Hello, my name is [John] and I will be your server today. Would you like to order drinks?\n\nGuest: Yes, I will have water, please.\n\nS: Still or sparkling?\n\nG: Sparkling.\n\nS: Lemon?\n\nG: Yes, please.\n\nКак вы видите, иногда не обязательно строить полные предложения и достаточно использовать ключевые слова. (Still or sparkling? Lemon?)\n\nАльтернативные фразы: What would you like to drink? Или Anything to drink?\n\nThe server brings the drink.\n\nS: Here you are. Are you ready to order?\n\nG: Yes, I’ll have a steak.\n\nS: How would you like it done?\n\nG: Medium.\n\nS: It comes with a side. Would you like French fries or steamed vegetables?\n\nG: I think I’ll go for fries.\n\nS: Alright. Anything else?\n\nG: No, that’ll be all.\n\nS: Great. Let me repeat your order. Steak medium and French fries on the side.\n\nG: That’s right.\n\nАльтернативные фразы:\n\nВместо Are you ready to order? – Готовы ли вы сделать заказ?, вы также можете сказать May I take your order? – Могу я принять у вас заказ?\n\nМы можем показывать то, что мы поняли собеседника короткими словам: Ok. Sure. Alright. Great.\n\nС помощью фразы Let me repeat your order мы подтверждаем заказ. Также можно сказать: So your order is …\n\nИ не забывайте улыбаться!\n\nНа сегодня всё. Повторяйте новые фразы каждый день и попробуйте разыграть похожую ситуацию с коллегами.\n\nHave a good day and see you soon!\n\nХочешь изучить тему подробнее? http://www.start2talk.ru/","images":["assets/remaining-courses/guru-25724-42707-0.jpg","assets/remaining-courses/guru-25724-42707-1.jpg"],"links":[{"title":"http://www.start2talk.ru/","url":"http://www.start2talk.ru/"}],"id":"42707"},{"title":"Общение в течение ужина","text":"Общение в течение ужина\n\nКурс предоставлен школой иностранного языка Star Talk. Читает преподаватель Чиркова Елена.\n\nЭто третья часть нашей серии обучающих видео на тему «Общение с иностранными посетителями ресторана». Продолжим беседу с гостем?\n\nS: Here is your steak. Be careful. The plate is hot.\n\nG: Thank you.\n\nS: Would you like anything else?\n\nG: Can I have some more napkins?\n\nS: Sure. Here you are. Enjoy your meal.\n\nАльтернативные фразы:\n\nМы говорим Here is (…) или Here you are!, когда подаем или протягиваем что-либо.\n\nЕсли вы забыли полный вариант вопроса Would you like anything else?, спросите Anything else?\n\nФраза Can I have (…) используется гостями, чтобы попросить вас принести что-либо. Наш гость просит принести еще салфеток => Can I have some more napkins?\n\nФразой Enjoy your meal! вы желаете посетителю приятного аппетита. Вы также можете сказать просто Enjoy!\n\nЕсли вы хотите спросить у гостей, всё ли им нравится, вот как вы можете это сделать:\n\nS: Is everything ok? Or How is the food?\n\nG: Good, thank you.\n\nНе забудьте про напитки! Если гость допил свой напиток, спросите не хочет ли он повторить.\n\nS: Would you like another water? or Would you like a refill?\n\nG: Yeah, that’d be great.\n\nКогда убираете тарелки, сначала уточните:\n\nS: Are you finished? or Can I take your plate?\n\nG: Oh no, I am still eating.\n\nЧто значит «Я всё ещё ем».\n\nИ, конечно, спросите про десерт.\n\nS: Would like a dessert? or How about a dessert?\n\nG: Sure.\n\nS: Here is our dessert menu.\n\nЕсли вы не захватили с собой меню, скажите I’ll bring you our dessert menu.\n\nG: What flavours of ice cream do you have?\n\nS: Chocolate, vanilla and strawberry.\n\nG: Hmmm. I’ll have vanilla please.\n\nS: Ok, vanilla ice cream (coming right up)\n\nНа сегодня всё. Практикуйте фразы, повторяя за нашими героями, и разыграйте похожие ситуации с своими коллегами. Have a good day and see you soon.\n\nХочешь изучить тему подробнее? Жми на http://www.start2talk.ru/","images":["assets/remaining-courses/guru-25724-42708-0.jpg","assets/remaining-courses/guru-25724-42708-1.jpg"],"links":[{"title":"http://www.start2talk.ru/","url":"http://www.start2talk.ru/"},{"title":"Видео к уроку","url":"https://www.youtube.com/embed/cxu935XlWEQ?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25724%2Flesson%2F42708&aoriginsup=1&vf=1"}],"id":"42708"},{"title":"Рекомендации и обсуждение меню.","text":"Рекомендации и обсуждение меню\n\nКурс предоставлен школой иностранного языка Star Talk. Читает преподаватель Чиркова Елена.\n\nСегодня я расскажу, какие английские фразы использовать, чтобы порекомендовать или рассказать о блюде или напитке.\n\nНачнем с рекомендаций.\n\nServer: May I take your order?\n\nGuest: Yes, I have a question. What appetizer would you recommend?\n\nS: Try the beef carpaccio. It comes with fresh arugula. It is delicious.\n\nG: I see. And what is the soup of the day?\n\nS: It is mushroom cream soup.\n\nG: And is your lasagne good?\n\nS: Yes. Also, we have vegetarian lasagne. \n\nG: Ok. I will have the beef carpaccio to start and the vegetarian lasagne as the main dish.\n\nДавайте вспомним, что принять заказ мы можем, спросив May I take you order now? или Are you ready to order?\n\nДать рекомендацию вы можете вот так. Короткий вариант: Try the beef carpaccio – попробуйте карпаччо из говядины. Или более длинный и более вежливый вариант – I would recommend the beef carpaccio. – Я бы порекомендовал карпаччо из говядины.\n\nЕсли у блюда есть гарнир, используйте фразу It comes with … – Оно подаётся с …\n\nBeef – говядина, а arugula – руккола.\n\nТакже, гость может спросить об ингредиентах или способе приготовления того или иного блюда.\n\nG: What is in the seafood pasta?\n\nS: There are mussels, clams, shrimps, fresh tomatoes, butter sauce and pasta, of course.\n\nG: And how is salmon cooked in the salmon risotto?\n\nS: It is pan-fried.\n\nКогда гость задает вопрос, самое главное – уловить вопросительное слово. Если это How? – как?, то он уточняет способ приготовления. How is chicken Kiev cooked/prepared? – Как готовится котлета по-киевски. Возможные ответы включают: grilled – приготовленный на гриле, pan-fried – пожаренный на сковороде, boiled – сваренный, steamed – приготовленный на пару. Как бы вы ответили на предыдущий вопрос?\n\nЕсли же в начале вопроса вы услышали What? – что? Какой?, то гостя интересует, что входит в состав блюда. Например, What is in the Tom Yam soup? – Что в супе Том Ям? Т.е. из чего он приготовлен?\n\nИли What is pelmeni? – Что такое пельмени? Кстати, на этот вопрос можно ответить вот так: Pelmeni is Russian dumplings with meat, usually beef or pork. – Пельмени – это русское название пельменей с мясом, обычно говядиной или свининой.\n\nНа этом на сегодня всё. Тренируйтесь описывать блюда из меню ресторана, в котором вы работаете, а мы увидимся с вами в следующем видео. Have a great day and see you soon!\n\nХочешь изучить тему подробнее? Жми на http://www.start2talk.ru/","images":["assets/remaining-courses/guru-25724-42709-0.jpg","assets/remaining-courses/guru-25724-42709-1.jpg"],"links":[{"title":"http://www.start2talk.ru/","url":"http://www.start2talk.ru/"},{"title":"Видео к уроку","url":"https://www.youtube.com/embed/9320N-D2fGk?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25724%2Flesson%2F42709&aoriginsup=1&vf=1"}],"id":"42709"},{"title":"Оплата счета","text":"Оплата счета.\n\nКурс предоставлен школой иностранного языка Star Talk. Читает преподаватель Чиркова Елена.\n\nВ этом видео уроке мы поговорим об оплате счёта на английском. Вот как может пройти разговор после того, как гость закончит есть.\n\nServer: How was everything?\n\nGuest: Everything was good. Thank you.\n\nS: Would you like anything else?\n\nG: No, I am good. Can I have the bill please? \n\nS: Yes, of course. Here you are.\n\nКогда вы видите, что гость закончил есть, спросите всё ли ему понравилось: How was everything? или Did you enjoy your meal/food? Если вдруг вы всё забыли, ограничьтесь Food good?\n\nУточните, не хочет ли он что-нибудь ещё Would you like anything else? – Не хотели ли вы что-нибудь ещё или просто Anything else? – Что-нибудь ещё?\n\nСлово bill или check означает счёт, и если вы услышали их в вопросе, значит гость просит принести счёт. Can we have the bill please? или Could we get the check please? – Можно нам счёт, пожалуйста.\n\nПри ответе можете уточнить I will get it for you right away. – Я вам его сейчас принесу.\n\nКогда вы увидите, что гость готов расплатиться, уточните Cash – наличные – или credit card – кредитная карта.\n\nS: Would you like to pay cash or credit card?\n\nG: Do you take Visa?\n\nS: Yes, we take all types of cards. I will get the POS machine.\n\n…\n\nS: Your pin code, please. Thank you. Here is your receipt. Thank you for coming. Enjoy the rest of your day.\n\nФразой Do you take …? гость уточняет, принимаете ли вы определённый вид карт, в данной ситуации - Виза.\n\nЕсли да, ответьте We take all types of cards – Мы принимаем все виды карт. Если нет, то скажите Sorry, we don’t take visa cards – Извините, мы не принимаем карты виза.\n\nЕсли гость расплачивается картой, вам пригодятся следующие фразы:\n\nPOS machine – терминал для оплаты кредитной картой.\n\nPin code – пинкод => Enter your pin code please. или Your pin code please.\n\nЕсли оплата наличными, то не забудьте про сдачу, если она нужна: Here is your change sir/madam.\n\nЕсли гость сказал Keep the change, сдачу вы можете оставить себе.\n\nИ в обоих случаях: Here is your receipt. – Вот ваш чек.\n\nВ самом конце поблагодарите гостя: Thank you for coming – Спасибо, что пришли.\n\nИ пожелайте хорошего дня: Have a good day. Enjoy your day/evening. Enjoy the rest of your day.\n\nНа этом всё. Не забудьте повторять фразы как можно чаще и найти партнёра для совместной практики.\n\nHave a good day!\n\nХочешь изучить тему подробнее? Жми на http://www.start2talk.ru/","images":["assets/remaining-courses/guru-25724-42710-0.jpg","assets/remaining-courses/guru-25724-42710-1.jpg"],"links":[{"title":"http://www.start2talk.ru/","url":"http://www.start2talk.ru/"},{"title":"Видео к уроку","url":"https://www.youtube.com/embed/2M_lrBS-QDM?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25724%2Flesson%2F42710&aoriginsup=1&vf=1"}],"id":"42710"},{"title":"Вино и безалкогольные напитки","text":"Вино и безалкогольные напитки\n\nКурс предоставлен школой иностранного языка Star Talk. Читает преподаватель Чиркова Елена.\n\nHello everybody. Привет всем. Меня зовут Елена. В нашей заключительной части серии обучающих видео мы поговорим о напитках. Давайте начнём как всегда с просмотра типичной ситуации в ресторане.\n\nServer: And this is our wine list.\n\nGuest: Thank you.\n\nS: We serve some wines by the glass. And we serve our house wines by the carafe too. We also have a wide selection of cocktails.\n\nG: I would like some red wine today. What is good?\n\nS: Do you prefer dry or sweet red wine?\n\nG: Dry.\n\nS: Then I would recommend the Australian Cabernet Sauvignon.\n\nG: Oh it is quite expensive. How about the house red? Is it any good?\n\nS: Yes, sir/madam. It is one of the most popular wines in our restaurant.\n\nG: Then I’ll get a glass of your house red.\n\nS: Sure. Coming right up.\n\nИтак, что мы увидели. Сначала наш герой предложил меню с напитками: This is our wine list. Вы также можете сказать Here is our wine list/drinks menu.\n\nWe serve – мы подаём => We serve some wines by the glass – дословно, мы подаём некоторые вина по бокалам, т.е. гость может заказать бокал, а не целую бутылку.\n\nЧасто в меню есть позиция домашнее вино – house wine, и его подают by the carafe – в графине или by the glass – в бокале.\n\nО наличии той или иной позиции можно говорить просто We have => We have a wide selection of cocktails – У нас широкий выбор коктейлей. Вот ещё пример, We have non-alcoholic beer - У нас есть безалкогольное пиво.\n\nВспомним, что рекомендации мы даём с помощью фразы I would recommend.\n\nMost popular – самый популярный => one of the most popular wines – один из самых популярных видов вина\n\nComing right up – дословно, придёт/будет принесён очень скоро – часто используется носителями языка, чтобы заверить гостя в том, что он получит свой заказ очень быстро.\n\nСлова и фразы по теме «Напитки»:\n\nSweet wine/Semi-sweet - сладкое вино/полусладкое\n\nDry wine - сухое вино\n\nWhiskey/scotch neat/on the rocks - виски/скотч чистый/со льдом\n\nA shot of (vodka) – стопка (водки)\n\nДавайте повторим и фразы про безалкогольные напитки.\n\nS: Would you like some still or sparkling water too?\n\nG: I’d like some still water.\n\nS: Would you like some ice with it?\n\nG: No, thank you.\n\nНу вот и всё, друзья. Это было последнее видео. Теперь ваша задача выучить эти фразы и научиться их применять в реальных ситуациях.\n\nСамый лучший вариант – объединиться с коллегами и практиковаться вместе.\n\nСпасибо, что смотрели нас. Удачи! Good luck!\n\nХочешь изучить тему подробнее? Жми на http://www.start2talk.ru/","images":["assets/remaining-courses/guru-25724-42711-0.jpg","assets/remaining-courses/guru-25724-42711-1.jpg"],"links":[{"title":"http://www.start2talk.ru/","url":"http://www.start2talk.ru/"},{"title":"Видео к уроку","url":"https://www.youtube.com/embed/BHfgQscRfLM?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25724%2Flesson%2F42711&aoriginsup=1&vf=1"}],"id":"42711"}],"outline":[{"type":"lesson","title":"Приветствие гостей","lessonIndex":0},{"type":"test","title":"Тест \"Приветствие гостей\""},{"type":"test","title":"Тест \"Прием заказа\""},{"type":"lesson","title":"Прием заказа","lessonIndex":1},{"type":"test","title":"Тест \"Общение во время ужина\""},{"type":"test","title":"Тест \"Рекомендации и обсуждение меню\""},{"type":"lesson","title":"Общение в течение ужина","lessonIndex":2},{"type":"test","title":"Тест \"Оплата счета\""},{"type":"test","title":"Тест \"Вино и безалкогольные напитки\""},{"type":"lesson","title":"Рекомендации и обсуждение меню.","lessonIndex":3},{"type":"lesson","title":"Оплата счета","lessonIndex":4},{"type":"lesson","title":"Вино и безалкогольные напитки","lessonIndex":5}],"testIds":["55942","55943","55944","55945","55946","55947"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('94441','test','Тест. Стандарты работы хостес','hostess-standards','{"id":"94441","title":"Тест. Стандарты работы хостес","timeLimitSeconds":260,"passCount":8,"questions":[{"id":"94441-1","text":"Какой стандарт внешнего вида хостес принят в Баре 90-е?","type":"single","options":["Нейтральный стиль: черные, белые и серые цвета","Стиль а-ля 80-е: соответствующие одежда и причёска","Стиль а-ля 90-е: яркие тени, маникюр, соответствующая причёска"]},{"id":"94441-2","text":"Какие документы и материалы из перечисленных должны находиться на рабочем месте хостес? Отметь верные варианты","type":"multiple","options":["Табель прихода/ухода, визитки, заполненная аптечка, “сигналы” о первом визите гостя","Личное расписание хостес, список всех гостей бара, бухгалтерские отчёты","Основное меню, барная шпаргалка, банкетное меню, анкеты для соискателей","Личные вещи сотрудников, список персонала, журнал жалоб"]},{"id":"94441-3","text":"Какие цвета используются в таблице бронирования и что они обозначают?","type":"single","options":["Красный – свободные столы, зелёный – занятые столы, жёлтый – отменённые брони","Зелёный – свободные столы, жёлтый – предбронирование, красный – брони с предоплатой","Белый – бронирование гостей, оранжевый – депозиты, чёрный – корпоративные столы","Синий – VIP-зона, фиолетовый – караоке, серый – стандартные брони"]},{"id":"94441-4","text":"Какие основные цели работы хостес?","type":"multiple","options":["Индивидуальный подход к каждому гостю","Быстрое распределение столов между гостями","Формирование активной развлекательной программы","Создание уютной атмосферы спокойствия и безопасности, гостеприимства и радушия"]},{"id":"94441-5","text":"Что категорически запрещено хостес во время работы?","type":"multiple","options":["Обсуждать с гостями внутренние вопросы бара, употреблять алкоголь","Информировать гостей о текущих акциях, проверять наличие столов","Спорить с гостем, игнорировать жалобы, нарушать дресс-код"]},{"id":"94441-6","text":"Как хостес должна встречать гостя, который пришёл без брони?","type":"multiple","options":["Уточнить его имя, номер телефона, предпочтения по залам","Озвучить условия депозита и предложить свободные столы","Оставить гостя ждать в зоне ожидания, пока освободится стол","Сразу направить его к барной стойке для уточнения свободных мест"]},{"id":"94441-7","text":"Какие важные детали должна уточнить хостес при бронировании стола?","type":"multiple","options":["Имя гостя, дату и время, количество персон, условия отдыха","Какие блюда и напитки гость планирует заказать","Только имя и номер телефона гостя","Знаком ли гость с баром и акциями, варианты оплаты, условия депозита"]},{"id":"94441-8","text":"Как хостес должна провожать гостя к столу?","type":"multiple","options":["Оставить гостя у входа и позволить ему выбрать стол самостоятельно","Идти впереди гостя, не теряя его из виду, поддерживать дистанцию","Идти рядом с гостем, предлагая ему напитки по дороге","Продолжать разговор, рассказывать об акциях и мероприятиях"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104548','test','Практическое задание по рассадке гостей','hostess-standards','{"id":"104548","title":"Практическое задание по рассадке гостей","timeLimitSeconds":900,"passCount":1,"questions":[{"id":"104548-1","text":"Практическое задание Теперь давайте попробуем применить полученные знания на практике. Представьте, что у вас есть схема зала ресторана и несколько групп гостей с разными пожеланиями. Ваша задача – разместить их так, чтобы удовлетворить их потребности и сбалансировать загрузку зала. Описание гостей: Пара на романтический ужин: Предпочитают столик у окна. Семья с детьми: Нужен просторный столик в тихой части зала. Бизнес-встреча: Требуется уединенное место для переговоров. Компания друзей: Желают сидеть ближе к бару. ❗Напиши ниже, куда рассадишь гостей исходя из вашей схемы зала!","type":"text","options":[]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104557','test','Тестирование','hostess-standards','{"id":"104557","title":"Тестирование","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"104557-1","text":"Куда лучше всего посадить гостя на инвалидном кресле?","type":"single","options":["Посадить за самый маленький и неудобный столик, чтобы никому не мешать","Оставить ждать в очереди, как и всех остальных","Быстро разместить в стороне от проходов и убрать лишний стул, если это необходимо","На второй этаж, откуда открывается красивый вид"]},{"id":"104557-2","text":"Как правильно начать разговор с гостем по телефону?","type":"single","options":["\"Алло, слушаю.\"","\"Добрый день! \"Бар 90-е\", меня зовут Анна. Чем я могу вам помочь?\"","\"Ресторан, чем помочь?\"","\"Кто говорит и зачем звоните?\""]},{"id":"104557-3","text":"Каким образом работа хостес может повлиять на увеличение среднего чека?","type":"single","options":["Быстро прогоняя гостей, чтобы освободить стол","Принимая оплату у гостей вместо официанта","Упоминая специальные предложения (дегустационные сеты, винные пары) и предлагая столики с лучшим видом","Предлагая гостям самые дешевые блюда"]},{"id":"104557-4","text":"Какие данные обязательно нужно записать при бронировании столика по телефону?","type":"single","options":["Полный паспортный данные гостя","Имя, дата и точное время брони, количество гостей, контактный телефон, особые пожелания","Только имя гостя и количество человек","Только время брони"]},{"id":"104557-5","text":"Какой главный принцип должна соблюдать хостес при рассадке гостей, чтобы обеспечить равномерную работу официантов?","type":"single","options":["Всегда заполнять столы в самой дальней части зала, чтобы создать уют","Сажать гостей только к тем официантам, которые нравятся хостес","Рассаживать группы гостей по очереди на каждую позицию (столы разных официантов), пока у всех не будет занято хотя бы по одному столу","Сажать гостей как можно компактнее, чтобы официанты меньше ходили"]},{"id":"104557-6","text":"Какую фразу категорически запрещено использовать при уточнении количества гостей?","type":"single","options":["\"Сколько вас будет человек?\"","\"Вы будете один?\" (по отношению к одному гостю)","\"На сколько персон готовить стол?\"","\"Вы планируете быть вдвоем?\""]},{"id":"104557-7","text":"К чему приводит эффективное управление бронированием и рассадкой?","type":"single","options":["К увеличению времени ожидания для гостей","К оптимизации заполняемости зала, минимизации времени ожидания и, как следствие, повышению общей выручки","К тому, что гости перестают приходить","К недовольству официантов из-за большой нагрузки"]},{"id":"104557-8","text":"В ресторане нет свободных мест, и образовалась очередь. Что хостес должна сделать в первую очередь согласно уроку?","type":"single","options":["Сказать гостям, что мест нет, и предложить прийти в другой день","Игнорировать очередь и заниматься своими делами","Отдать приоритет большой компании, которая только что вошла","Попросить гостей подождать, указав реальное время, и записать их в лист ожидания"]},{"id":"104557-9","text":"При рассадке посетителей, что должно иметь приоритет над равномерной загрузкой официантов?","type":"single","options":["Пожелания и предпочтения самих гостей","Цвет одежды гостей","Наличие свободных столов на кухне","Желание хостес поскорее закончить смену"]},{"id":"104557-10","text":"Семья с маленькими детьми пришла в ресторан. Какое место будет для них наиболее комфортным?","type":"single","options":["Столик рядом с баром и громкой музыкой","Высокие стулья у барной стойки","Уединенный столик в центре зала, чтобы все видели детей","Столик в тихой части зала, вдали от интенсивных проходов"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('100075','test','Тест по 1-й смене','waiter-internship','{"id":"100075","title":"Тест по 1-й смене","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"100075-1","text":"К какому времени зал должен быть полностью готов к работе?","type":"single","options":["К 17:45","К 18:15","К 18:00"]},{"id":"100075-2","text":"Какой внешний вид считается нарушением стандартов?","type":"single","options":["Неряшливая форма, неухоженные волосы, грязная обувь","Джинсовка и аксессуары в стиле 90-х","Минимальный макияж"]},{"id":"100075-3","text":"Что считается нарушением дисциплины?","type":"single","options":["Смена без бейджа","Опоздание без предупреждения менеджера","Отсутствие аксессуаров 90-х в образе"]},{"id":"100075-4","text":"Как часто разрешено выходить на перекур во время работы?","type":"single","options":["Только когда в зале нет гостей и позиции прикрыты","Один раз в час, независимо от ситуации","Неограниченно, если есть время"]},{"id":"100075-5","text":"Во сколько сотрудник бара обязан прибыть на смену в пятницу?","type":"single","options":["К 16:30","К 16:45","К 17:00"]},{"id":"100075-6","text":"Что делать, если форма испачкалась во время смены?","type":"single","options":["Продолжить работать до конца смены","Спрятать пятно под фартуком","Привести форму в порядок или заменить на чистую"]},{"id":"100075-7","text":"Что необходимо сделать после перекура, прежде чем вернуться к работе?","type":"single","options":["Освежить дыхание и убедиться, что одежда не пахнет дымом","Проверить телефон","Сразу вернуться в зал"]},{"id":"100075-8","text":"Что нужно сделать, если понимаешь, что опаздываешь на смену?","type":"single","options":["Прийти как можно быстрее, не предупреждая","Немедленно сообщить менеджеру и уточнить, требуется ли замена","Написать коллеге, чтобы передал сообщение"]},{"id":"100075-9","text":"Почему внешний вид официанта — часть стандарта обслуживания?","type":"single","options":["Потому что гость оценивает качество заведения по чистоте и опрятности персонала","Потому что так удобнее для фотоотчётов","Потому что это требование менеджера"]},{"id":"100075-10","text":"Почему запрещено ходить курить толпой?","type":"single","options":["Это может не понравиться гостям","Потому что зал должен оставаться под контролем — кто-то обязан быть на месте","Так требует охрана"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('100153','test','Тест по 2-й смене','waiter-internship','{"id":"100153","title":"Тест по 2-й смене","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"100153-1","text":"Какие действия необходимо выполнить с входной группой?","type":"single","options":["Протереть стекла","Оставить на проверку менеджеру","Проверить параметры: чистота пола, подоконников, коврика, пепельницы, включение вентиляции","Проверить ковёр"]},{"id":"100153-2","text":"Что должно быть в идеальном порядке в гостевом туалете?","type":"single","options":["Только чистота пола","Мыло, полотенца, смыв, чистота","Только сантехника","Только наличие туалетной бумаги"]},{"id":"100153-3","text":"Как должен выглядеть порядок в подсобке?","type":"single","options":["Обувь на полке, вещи на вешалке, ничего не валяется","Всё должно быть разложено","Проверяются только шкафчики","Проверка не требуется"]},{"id":"100153-4","text":"Какой уровень наполнения соли и перца считается правильным?","type":"single","options":["Только если заканчивается","Полный","На ¾ емкости","Наполовину"]},{"id":"100153-5","text":"Как проверяется исправность терминала перед сменой?","type":"single","options":["Проверять только при необходимости","Убедиться, что работает и есть чековая лента","Просто включить","Проверить только наличие ленты"]},{"id":"100153-6","text":"Какой инструмент помогает официанту держать всё под контролем при открытии смены?","type":"single","options":["Чек-лист","График смен","Лист заказов","Инструкция по безопасности"]},{"id":"100153-7","text":"Что входит в обязательную проверку стейшена?","type":"single","options":["Проверка формы персонала","Терминалы и меню","Только салфетки","Полироль, тряпки, салфетки, сахар, зубочистки"]},{"id":"100153-8","text":"Как правильно подготовить столовые приборы?","type":"single","options":["Протереть сухой тряпкой","Ополоснуть в кипятке и натереть до блеска","Вымыть в прохладной воде","Сложить без проверки"]},{"id":"100153-9","text":"Какое должно быть состояние меню при открытии зала?","type":"single","options":["Достаточно просто заменить грязные","Можно использовать даже слегка повреждённые меню","Чистое, без рваных страниц, протёртое влажной тряпкой","Меню не требует проверки"]},{"id":"100153-10","text":"Какие элементы зала необходимо проверить перед открытием?","type":"single","options":["Только стулья","Только столы и салфетки","Только терминалы","Пол, стулья, столы, подоконники"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('100159','test','Тест по 3-й смене','waiter-internship','{"id":"100159","title":"Тест по 3-й смене","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"100159-1","text":"Как официант должен сообщать о времени приготовления?","type":"single","options":["Обещать минимальное время","Говорить «скоро будет»","Честно сказать реальное время"]},{"id":"100159-2","text":"Как официант должен заходить к гостю?","type":"single","options":["С улыбкой и на позитиве, создавая атмосферу 90-х","Без эмоций, сразу подавая меню","Спокойно и официально"]},{"id":"100159-3","text":"Как правильно делать чек-бэк?","type":"single","options":["Проявлять искренний интерес, считывать эмоции гостя","Спрашивать только, если гость выглядит недовольным","Спросить «Всё в порядке?»"]},{"id":"100159-4","text":"Что важно сделать при подаче меню?","type":"single","options":["Спросить, хочет ли гость что-то заказать сразу","Оставить на столе без слов","Подавать открытой рукой, предложить освежающий напиток"]},{"id":"100159-5","text":"Как лучше всего задавать вопросы гостю во время чек-бэка?","type":"single","options":["Чётко и официально","Строго по шаблону","С искренним интересом, без шаблонных фраз"]},{"id":"100159-6","text":"Зачем делать контрольный чек-бэк?","type":"single","options":["Уточнить сумму счета","Проверить, понравился ли официант","Закрепить положительное впечатление перед уходом"]},{"id":"100159-7","text":"Какой вопрос НЕ стоит задавать гостю при чек-бэке?","type":"single","options":["«Как вам блюдо?»","«Всё ли в порядке?»","«Хотите ли попробовать что-то еще?»"],"editorialNote":"Ключ Сервис Гуру требует методической проверки: для вопроса с отрицанием источник принимает «Как вам блюдо?». Повторно подтверждено в интерфейсе."},{"id":"100159-8","text":"Когда официант должен делать текущий чек-бэк?","type":"single","options":["Через 2-3 минуты после первой вилки еды","После того, как гость полностью съел блюдо","Сразу после подачи блюда"]},{"id":"100159-9","text":"Что такое Check Back (чек-бэк)?","type":"single","options":["Обратная связь с гостем о качестве еды и сервиса","Проверка счета гостя","Оценка работы персонала"]},{"id":"100159-10","text":"Какой приём помогает увеличить продажу блюд?","type":"single","options":["Просто назвать позиции из меню, гость разберется по ходу заказа","Дать гостю меню и уйти, тогда он сам закажет все, что нужно","Описание блюд с эмоциями и аппетитными деталями"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('100172','test','Тест по 4-й смене','waiter-internship','{"id":"100172","title":"Тест по 4-й смене","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"100172-1","text":"Какое назначение у бокала Олд фэшн?","type":"single","options":["Для горячих напитков","Для лимонадов","Для подачи вина","Для коктейлей с льдом"]},{"id":"100172-2","text":"Для чего используется медная кружка?","type":"single","options":["Для подачи лимонада","Для коктейля \"Московский мул\"","Для коктейля \"Маргарита\"","Для глинтвейна"]},{"id":"100172-3","text":"Для чего используется штоф?","type":"single","options":["Для лимонадов","Для вина","Для крепких спиртных напитков","Для коктейлей со льдом"]},{"id":"100172-4","text":"Какое назначение у френч-пресса?","type":"single","options":["Для подачи коньяка","Для охлаждения коктейлей","Для взбивания молока","Для заваривания чая"]},{"id":"100172-5","text":"Тики бокалы используются для:","type":"single","options":["Тропических коктейлей","Для кофе","Горячих напитков","Вина"]},{"id":"100172-6","text":"Что обязан указать каждый сотрудник в личной карте Telegram?","type":"single","options":["Должность","Дату рождения","Фамилию и имя"]},{"id":"100172-7","text":"Можно ли шутить в рабочих чатах?","type":"single","options":["Нельзя","Чем чаще, тем лучше","Можно, но в разумных пределах"]},{"id":"100172-8","text":"Почему кубок используют для горячих напитков?","type":"single","options":["Длинная ножка помогает не обжечься","Имеет специальную форму","У него толстые стенки"]},{"id":"100172-9","text":"В каком бокале подают коктейль «Лонг Айленд»?","type":"single","options":["Дабл хайбол","Рокс","Тики бокал","Олд фэшн"]},{"id":"100172-10","text":"В каком бокале подаётся коктейль «Младший лейтенант»?","type":"single","options":["Эклипс","Коктейльная рюмка","Дабл хайбол"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104138','test','Тест по 5-й смене','waiter-internship','{"id":"104138","title":"Тест по 5-й смене","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"104138-1","text":"У тебя на станции закончились бумажные салфетки, а зал полон. Что делать?","type":"single","options":["Подождать, пока кто-то из гостей попросит, и тогда сходить","Сразу доложить салфетки — на станции всегда должен быть запас","Ничего, официанты сами возьмут со своих станций","Попросить гостей пользоваться влажными салфетками"]},{"id":"104138-2","text":"Какие блюда в меню считаются «топ-позициями» и чаще всего заказывают компании?","type":"single","options":["Самые дорогие позиции в меню","Блюда, которые быстро готовятся","Только десерты","Блюда на компанию (большие сеты и плато)"]},{"id":"104138-3","text":"Если ты заметил, что блюдо выглядит не так, как должно (соус размазан, гарнир не на месте), твои действия?","type":"single","options":["Отнести гостю — может, не заметит","Вернуть поварам и объяснить, что не так","Быстро поправить пальцем и отнести","Позвать гостя и спросить, хочет ли он такое блюдо"]},{"id":"104138-4","text":"Ты подошел к раздаче и видишь готовое блюдо. Что нужно проверить в первую очередь?","type":"single","options":["Температуру тарелки","Наличие чека на столе у гостя","Внешний вид: аккуратность выкладки, чистоту краев тарелки, свежесть ингредиентов","Вес блюда"]},{"id":"104138-5","text":"Гость спрашивает: «Сколько ждать мое блюдо?» От чего зависит твой ответ?","type":"single","options":["Надо сказать «скоро», чтобы не расстраивать","Надо посмотреть на часы и назвать случайное число","От настроения поваров","От загруженности кухни и времени приготовления категории блюда"]},{"id":"104138-6","text":"Где изображен Хайбол 295 мл. Подается к холодным б/а напиткам (сок, морс, лимонад, кола и т.д), холодным литровым алко коктейлям (Алёшка), к пиву. Также в нем отдаются некоторые коктейли вроде (лав из, секс на пляже и т.д)","type":"single","options":["Вариант 1","Вариант 2","Вариант 3"],"originalOptionLabels":[" Хайбол 295 мл."," Хайбол 295 мл."," Хайбол 295 мл."],"optionImages":["assets/assessment-options/104138-6-0.jpg","assets/assessment-options/104138-6-1.jpg","assets/assessment-options/104138-6-2.jpg"]},{"id":"104138-7","text":"что за бокал на фотографии?","type":"single","options":["Ревел Ап 500 мл.- Форма бокала поможет напитку насытиться кислородом, что раскроет его вкус и аромат. Подходит для отдачи красного, белого и игристого вина, также подается к шампанскому.","Шалле 300 мл. - Коктейльный бокал  (Порнстар Мартини, Кловер Клаб)","Винный бокал 385 мл. - Для вина, коктейлей."],"image":"assets/assessment-options/104138-7.jpg"},{"id":"104138-8","text":"Что изображено на фото?","type":"single","options":["Коктейльная рюмка 190 мл. - В нем подают охлажденные коктейли среднего объема, но без льда. Не используется для подачи напитков со льдом и в чистом виде (в т.ч. и вермута Мартини, несмотря на название).","Маргаритка 250 мл. - Бокал под коктейль «Маргарита».","Кубок  300 мл. - Для горячих напитков (глинтвейна), т.к. у него толстые стенки."],"image":"assets/assessment-options/104138-8.jpg"},{"id":"104138-9","text":"Зачем нужен Штоф 0.5 л.?","type":"single","options":["Сосуд для крепких спиртных напитков например: водка, виски, ром, текила, джин, бренди.","Используется для отдачи коктейлей (Мальчик хочет в Таиланд, Голубая лагуна, Младший лейтенант, Лонг Айленд, Галлюцинации фрекен бок и т.д) Также используется для отдачи лимонадов (Цитрусовый, ягодный, огуречный)","Используется для подачи (Лимонадов, сока, морса, коктейля Алешка)"],"image":"assets/assessment-options/104138-9.jpg"},{"id":"104138-10","text":"Акции в нашем баре могут меняться. Что нужно делать, чтобы всегда быть в курсе актуальных предложений?","type":"single","options":["Спрашивать у гостей, какие акции они видели в интернете","Ждать, когда менеджер лично подойдет и расскажет","Читать старые рассылки в чате","Перед каждой сменой уточняй акции у менеджера, старшего смена, на сайте бара."]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104142','test','Тест по 6-й смене','waiter-internship','{"id":"104142","title":"Тест по 6-й смене","timeLimitSeconds":180,"passCount":6,"questions":[{"id":"104142-1","text":"Что произойдет после нажатия кнопки «Печать»?","type":"single","options":["Откроется окно оплаты","Распечатается чек для гостя","Заказ отправится на кухню, блюда начнут готовить","Стол освободится для новых гостей"]},{"id":"104142-2","text":"Ты подошел к терминалу, чтобы начать работу. С чего нужно начать?","type":"single","options":["Прокатить свою личную карту или ввести PIN-код","Нажать кнопку «Открыть кассовую смену»","Сразу нажать на свободный стол и открыть заказ","Позвать наставника, чтобы он авторизовал тебя"]},{"id":"104142-3","text":"Ты начал открывать заказ на свободный стол. Что нужно сделать сразу после выбора стола?","type":"single","options":["Спросить у гостей, будут ли они заказывать алкоголь","Добавить первое блюдо","Распечатать пречек","Ввести количество гостей"]},{"id":"104142-4","text":"На схеме зала стол, за который сели гости, горит красным. Что это значит?","type":"single","options":["На этом столе уже есть открытый заказ","За этим столом сидят VIP-персоны","За этим столом нельзя принимать заказы до 18:00","Стол не убран после прошлых гостей"]},{"id":"104142-5","text":"Ты добавил блюдо в заказ, но понял, что ошибся, и оно еще не отправлено на кухню. Как исправить ошибку?","type":"single","options":["Нажать на блюдо в заказе и выбрать «Удалить»","Позвать менеджера для удаления","Отменить весь заказ и создать новый","Ничего не делать — гость сам скажет, если что-то не так"]},{"id":"104142-6","text":"Гость просит добавить еще одно блюдо после того, как заказ уже ушел на кухню. Твои действия?","type":"single","options":["Позвать наставника для создания дозаказа","Создать новый заказ на этот же стол","Сказать, что нельзя — заказ уже готовится","Добавить блюдо в существующий заказ и снова нажать «Печать»"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104144','test','Тест по 7-й смене','waiter-internship','{"id":"104144","title":"Тест по 7-й смене","timeLimitSeconds":150,"passCount":5,"questions":[{"id":"104144-1","text":"Ты помогаешь наставнику и несешь гостю тарелку с горячим блюдом. Как правильно ее держать?","type":"single","options":["Держать за край, как книгу","Большим пальцем касаясь еды — так удобнее и надежнее","Двумя руками, прижимая тарелку к груди","Большой палец на бортике тарелки, остальные поддерживают снизу"]},{"id":"104144-2","text":"Тебе нужно убрать со стола грязную посуду после того, как гости поели. Как правильно это сделать?","type":"single","options":["Попросить гостей передать посуду","Сложить все тарелки друг на друга прямо у стола, грязные приборы сверху","Сначала убрать бокалы, потом тарелки отдельно","Аккуратно собрать тарелки, не складывая грязное в чистые остатки, приборы положить сверху"]},{"id":"104144-3","text":"Ты несешь гостю бокал с белым вином. Как правильно его держать?","type":"single","options":["За основание, поддерживая снизу","Двумя руками, обхватив чашу","Только за ножку, чтобы не нагревать вино и не оставлять отпечатков","За верхнюю часть чаши — так удобнее передавать"]},{"id":"104144-4","text":"У тебя появилась свободная минута, пока наставник общается с гостями. Чем лучше всего заняться?","type":"single","options":["Выйти на улицу подышать воздухом","Посмотреть в телефон, отдохнуть","Взять планшет и создать несколько тренировочных заказов в iiko","Подойти к стойке и пообщаться с коллегами"]},{"id":"104144-5","text":"При создании тренировочного заказа с модификаторами (например, стейк разной прожарки), на что нужно обратить внимание?","type":"single","options":["Чтобы заказ был создан на свободный стол","Чтобы цена блюда была максимальной","Чтобы были выбраны все обязательные модификаторы","Чтобы заказ был отправлен на кухню"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
